module find_crash_line #(\n    parameter MAX_N = 256,\n    parameter N_WIDTH = 8,\n    parameter R_WIDTH = 32,\n    parameter P_WIDTH = 32,\n    parameter RESULT_WIDTH = 64\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [N_WIDTH-1:0] n,\n    input wire [R_WIDTH-1:0] r,\n    input wire [P_WIDTH-1:0] p,\n    output reg [RESULT_WIDTH-1:0] result,\n    output reg done\n);\n\n// State encoding\nlocalparam [1:0] IDLE = 2'd0;\nlocalparam [1:0] COMPUTE_M = 2'd1;\nlocalparam [1:0] COMPUTE_S = 2'd2;\nlocalparam [1:0] DONE_STATE = 2'd3;\n\nreg [1:0] state, next_state;\nreg [N_WIDTH-1:0] m;\nreg [N_WIDTH-1:0] s;\nreg [RESULT_WIDTH-1:0] best;\nreg [RESULT_WIDTH-1:0] f [1:MAX_N];\nreg [7:0] cycle_count;\nlocalparam [7:0] MAX_CYCLES = 8'd1000;\n\n// Combinational signals\nwire [N_WIDTH-1:0] k;\nwire [RESULT_WIDTH-1:0] mult;\nwire [RESULT_WIDTH-1:0] f_k;\nwire [RESULT_WIDTH-1:0] cost;\n\nassign k = (m + s - 1) / s;\nassign mult = (s - 1) * p;\nassign f_k = f[k];\nassign cost = mult + r + f_k;\n\n// State transition logic\nalways @(*) begin\n    case (state)\n        IDLE: begin\n            if (start) begin\n                next_state = COMPUTE_M;\n            end else begin\n                next_state = IDLE;\n            end\n        end\n        COMPUTE_M: begin\n            if (m > n) begin\n                next_state = DONE_STATE;\n            end else begin\n                next_state = COMPUTE_S;\n            end\n        end\n        COMPUTE_S: begin\n            if (s > m) begin\n                next_state = COMPUTE_M;\n            end else begin\n                next_state = COMPUTE_S;\n            end\n        end\n        DONE_STATE: begin\n            next_state = IDLE;\n        end\n        default: next_state = IDLE;\n    endcase\nend\n\n// Sequential logic\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= {RESULT_WIDTH{1'b0}};\n        m <= {N_WIDTH{1'b0}};\n        s <= {N_WIDTH{1'b0}};\n        best <= {RESULT_WIDTH{1'b0}};\n        cycle_count <= 8'd0;\n        integer i;\n        for (i = 1; i < MAX_N; i = i + 1) begin\n            f[i] <= {RESULT_WIDTH{1'b0}};\n        end\n    end else begin\n        state <= next_state;\n        cycle_count <= cycle_count + 8'd1;\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    f[1] <= {RESULT_WIDTH{1'b0}};\n                    m <= 2;\n                end\n            end\n            COMPUTE_M: begin\n                if (m > n) begin\n                    result <= f[n];\n                    done <= 1'b1;\n                end else begin\n                    best <= {RESULT_WIDTH{1'b1}};\n                    s <= 2;\n                end\n            end\n            COMPUTE_S: begin\n                if (s > m) begin\n                    f[m] <= best;\n                    m <= m + 1;\n                end else begin\n                    if (cost < best) begin\n                        best <= cost;\n                    end\n                    s <= s + 1;\n                end\n            end\n            DONE_STATE: begin\n                // Stay in DONE_STATE until reset\n            end\n        endcase\n    end\nend\n\nendmodule